//! Signing parity with GRVT's official Python signers (`tests/vectors.json`, generated by
//! `tests/gen_vectors.py`). EIP-712 signatures are deterministic, so request bodies, including
//! `r`/`s`/`v`, must match exactly.

use roshar_grvt::signer::{
    domain_separator, order_struct_hash, NewOrder, NewOrderLeg, OrderBuilder, Signer,
};
use roshar_grvt::types::{GrvtCreateOrderRequest, GrvtTimeInForce};
use serde_json::Value;

fn load() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn hex32(b: &[u8; 32]) -> String {
    format!("0x{}", hex::encode(b))
}

fn tif(s: &str) -> GrvtTimeInForce {
    serde_json::from_value(Value::String(s.to_string())).unwrap()
}

fn new_order(case: &Value) -> NewOrder {
    let o = &case["request"]["order"];
    let instruments = &case["instruments"];
    let legs = o["legs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|l| {
            let name = l["instrument"].as_str().unwrap();
            let inst = &instruments[name];
            NewOrderLeg {
                instrument: name.to_string(),
                instrument_hash: inst["instrument_hash"].as_str().unwrap().to_string(),
                base_decimals: inst["base_decimals"].as_u64().unwrap() as u32,
                size: l["size"].as_str().unwrap().to_string(),
                limit_price: l["limit_price"].as_str().unwrap().to_string(),
                is_buying_asset: l["is_buying_asset"].as_bool().unwrap(),
            }
        })
        .collect();
    let builder = o.get("builder").map(|b| OrderBuilder {
        address: b.as_str().unwrap().to_string(),
        fee: o["builder_fee"].as_str().unwrap().to_string(),
    });
    NewOrder {
        sub_account_id: o["sub_account_id"].as_str().unwrap().parse().unwrap(),
        is_market: o["is_market"].as_bool().unwrap(),
        time_in_force: tif(o["time_in_force"].as_str().unwrap()),
        post_only: o["post_only"].as_bool().unwrap(),
        reduce_only: o["reduce_only"].as_bool().unwrap(),
        legs,
        client_order_id: o["metadata"]["client_order_id"]
            .as_str()
            .unwrap()
            .parse()
            .unwrap(),
        builder,
        nonce: o["signature"]["nonce"].as_u64().unwrap() as u32,
        expiration_ns: o["signature"]["expiration"]
            .as_str()
            .unwrap()
            .parse()
            .unwrap(),
    }
}

#[test]
fn orders_match_sdk() {
    let v = load();
    let key = v["private_key"].as_str().unwrap();
    let cases = v["orders"].as_array().unwrap();
    assert!(cases.len() >= 9);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let chain_id = case["chain_id"].as_u64().unwrap();
        let signer = Signer::from_hex(key, chain_id).unwrap();
        assert_eq!(signer.address(), v["address"].as_str().unwrap(), "{name}");

        let order = new_order(case);
        assert_eq!(
            hex32(&domain_separator(chain_id)),
            case["domain_separator"].as_str().unwrap(),
            "{name}: domain separator"
        );
        assert_eq!(
            hex32(&order_struct_hash(&order).unwrap()),
            case["struct_hash"].as_str().unwrap(),
            "{name}: struct hash"
        );
        assert_eq!(
            hex32(&signer.order_digest(&order).unwrap()),
            case["digest"].as_str().unwrap(),
            "{name}: digest"
        );

        let body = GrvtCreateOrderRequest {
            order: signer.sign_order(&order).unwrap(),
        };
        assert_eq!(
            serde_json::to_value(&body).unwrap(),
            case["request"],
            "{name}: request body"
        );
    }
}

#[test]
fn wallet_logins_match_builder_examples() {
    let v = load();
    let key = v["private_key"].as_str().unwrap();
    for case in v["wallet_logins"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let signer = Signer::from_hex(key, case["chain_id"].as_u64().unwrap()).unwrap();
        let nonce = case["nonce"].as_u64().unwrap() as u32;
        let expiration: i64 = case["expiration"].as_str().unwrap().parse().unwrap();
        assert_eq!(
            hex32(signer.domain_separator()),
            case["domain_separator"].as_str().unwrap(),
            "{name}: domain separator"
        );
        assert_eq!(
            hex32(&signer.wallet_login_digest(nonce, expiration)),
            case["digest"].as_str().unwrap(),
            "{name}: digest"
        );
        let body = signer.sign_wallet_login(nonce, expiration).unwrap();
        assert_eq!(
            serde_json::to_value(&body).unwrap(),
            case["request"],
            "{name}: request body"
        );
    }
}

#[test]
fn rejects_unsignable_orders() {
    let v = load();
    let key = v["private_key"].as_str().unwrap();
    let signer = Signer::from_hex(key, 325).unwrap();
    let base = new_order(&v["orders"][0]);

    let mut rpi = base.clone();
    rpi.time_in_force = GrvtTimeInForce::RetailPriceImprovement;
    assert!(signer.sign_order(&rpi).is_err());

    let mut too_precise = base.clone();
    too_precise.legs[0].size = "0.0000000001".to_string();
    assert!(signer.sign_order(&too_precise).is_err());

    let mut no_legs = base;
    no_legs.legs.clear();
    assert!(signer.sign_order(&no_legs).is_err());
}
